package com.travelbird.ai.service;
import com.travelbird.ai.entity.AiPreviewRetentionStatus;import com.travelbird.ai.repository.*;import java.time.*;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class AiPreviewExpiryService{private final AiPreviewExpiryRepository candidates;private final AiTripPreviewRepository previews;private final Clock clock;public AiPreviewExpiryService(AiPreviewExpiryRepository c,AiTripPreviewRepository p,Clock clock){candidates=c;previews=p;this.clock=clock;}@Transactional public void expireDuePreviews(){var now=LocalDateTime.now(clock);for(Long id:candidates.findExpiredIds(now)){var p=previews.findByIdForGate(id).orElse(null);if(p!=null&&p.getRetentionStatus()==AiPreviewRetentionStatus.TEMPORARY&&p.getExpiresAt()!=null&&!p.getExpiresAt().isAfter(now))p.expireContent(now);}}}
